"use client";

import Link from "next/link";
import { useEffect, useState } from "react";
import LogoIcon from "./LogoIcon";

export default function Nav() {
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 60);
    window.addEventListener("scroll", onScroll);
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  return (
    <nav
      className={`fixed top-0 left-0 right-0 z-[100] flex items-center justify-between px-8 md:px-16 py-6 transition-colors duration-400 ${
        scrolled
          ? "bg-paper/92 backdrop-blur-md border-b border-border"
          : "bg-transparent"
      }`}
    >
      <Link
        href="#home"
        className="flex items-center gap-2 text-ink no-underline group"
      >
        <span className="text-accent transition-transform group-hover:scale-110">
          <LogoIcon className="w-5 h-5 md:w-6 md:h-6" />
        </span>
        <span
          className="font-medium text-xl md:text-2xl tracking-tight"
          style={{ fontFamily: "var(--font-loader-mono), ui-monospace, monospace" }}
        >
          Miel
        </span>
      </Link>
      <ul className="flex gap-10 list-none">
        <li>
          <Link href="#about" className="nav-link-underline text-ink text-[0.8rem] font-medium tracking-[0.12em] uppercase no-underline">
            About
          </Link>
        </li>
        <li>
          <Link href="#work" className="nav-link-underline text-ink text-[0.8rem] font-medium tracking-[0.12em] uppercase no-underline">
            Work
          </Link>
        </li>
        <li>
          <Link href="#education" className="nav-link-underline text-ink text-[0.8rem] font-medium tracking-[0.12em] uppercase no-underline">
            Education
          </Link>
        </li>
        <li>
          <Link href="#contact" className="nav-link-underline text-ink text-[0.8rem] font-medium tracking-[0.12em] uppercase no-underline">
            Contact
          </Link>
        </li>
      </ul>
    </nav>
  );
}
